,{"id":"768ad3fa-d46a-41bd-89ab-615d2e2961ea","text":"Ag"}],"correctAnswerId":"6277b337-47d1-402b-957a-1c61582fa651","roundId":null},{"id":"9fa2f45d-6ac7-4d8c-9b87-87ac989edde2","text":"How many continents are there?","answers":[{"id":"4250b702-5472-4ee3-83e8-93979579a73f","text":"5"},{"id":"a39b1876-59bf-4eb8-9cd5-bf7e77a83d60","text":"6"},{"id":"e18d9e31-7b62-450a-868c-eac7a4c8f771","text":"7"},{"id":"aa8399a5-3627-4f8e-b08c-61cf88124a42","text":"8"}],"correctAnswerId":"e18d9e31-7b62-450a-868c-eac7a4c8f771","roundId":null},{"id":"1af876b2-a745-4010-8016-934c5cae84d2","text":"Which ocean is the largest?","answers":[{"id":"8101da57-4de8-4a95-a48f-1c4251e77c6e","text":"Atlantic"},{"id":"598455ab-c2af-41b0-b04c-906315417240","text":"Indian"},{"id":"3068279b-81ae-4550-8707-e65115b520ce","text":"Arctic"},{"id":"871aff07-9ca0-48a7-a26c-16747d6e8122","text":"Pacific"}],"correctAnswerId":"871aff07-9ca0-48a7-a26c-16747d6e8122","roundId":null},{"id":"f1583ff1-e1a6-4d91-aa36-de8f2344a1e6","text":"In what year did World War II end?","answers":[{"id":"976397b1-f842-4950-8f88-e6e6774a8a34","text":"1943"},{"id":"818109aa-dcc6-42a4-ae82-00cb74287e16","text":"1944"},{"id":"36b0f127-7f55-4be1-b658-0653b540257d","text":"1945"},{"id":"c88040a4-a910-4bb5-a681-a8a2c276b7ad","text":"1946"}],"correctAnswerId":"36b0f127-7f55-4be1-b658-0653b540257d","roundId":null},{"id":"0f67a6ff-35df-4a14-98c6-430f94954408","text":"What gas do plants absorb from the atmosphere?","answers":[{"id":"e3d64ff6-7777-4cae-b020-b06502d3ffae","text":"Oxygen"},{"id":"2f1dbfa7-9c0e-48dc-b1a8-8eec849c2e32","text":"Nitrogen"},{"id":"2b03d363-df09-4788-848b-373850e0deec","text":"Carbon dioxide"},{"id":"8a5fba46-f463-4715-a988-4f385bd7102c","text":"Hydrogen"}],"correctAnswerId":"2b03d363-df09-4788-848b-373850e0deec","roundId":null},{"id":"ec252815-c569-48ff-a702-1e0795180959","text":"How many sides does a hexagon have?","answers":[{"id":"9f23fa53-7cd2-4114-9802-3b7242ef72d2","text":"5"},{"id":"361bd99c-aa2e-4b8f-bfc4-06