  v_bingo_config jsonb := $bingo${"tracks":[{"id":"5701f05a-870c-4673-9e7b-0de798dbccc6","title":"Bohemian Rhapsody","artist":"Queen","audioUrl":""},{"id":"d9c614e1-c039-4a33-be19-dfbf22413570","title":"Billie Jean","artist":"Michael Jackson","audioUrl":""},{"id":"a1328838-3dce-4dad-aba1-57a2a19d04e4","title":"Hey Jude","artist":"The Beatles","audioUrl":""},{"id":"069405bc-79e6-45b3-8473-48d8a528313c","title":"Smells Like Teen Spirit","artist":"Nirvana","audioUrl":""},{"id":"4d75de6f-1ec4-4ec5-b802-acff8bc271a1","title":"Wonderwall","artist":"Oasis","audioUrl":""},{"id":"53ba6dda-902b-4779-92ca-7e0ada8fb5ef","title":"Rolling in the Deep","artist":"Adele","audioUrl":""},{"id":"65ac5d0f-4012-4163-9e17-ff58fa00b1dd","title":"Uptown Funk","artist":"Bruno Mars","audioUrl":""},{"id":"8197624b-df81-4367-b01b-79dd1c329954","title":"Shape of You","artist":"Ed Sheeran","audioUrl":""},{"id":"b8a44782-1b6e-4aa9-95c8-899705d8d164","title":"Blinding Lights","artist":"The Weeknd","audioUrl":""},{"id":"b42b13c8-284b-4e51-a39c-4a5bd89ab328","title":"Hotel California","artist":"Eagles","audioUrl":""},{"id":"2f8c91b4-8f00-40b9-b513-985c829ba13a","title":"Sweet Child O Mine","artist":"Guns N' Roses","audioUrl":""},{"id":"61621811-8fd2-4fab-988e-648b15d85ca4","title":"Livin on a Prayer","artist":"Bon Jovi","audioUrl":""},{"id":"1e0626f9-bbfd-423d-b391-5311fd3375c5","title":"Don't Stop Believin'","artist":"Journey","audioUrl":""},{"id":"48895731-91a8-4ff7-8eea-02ea89d601e9","title":"Africa","artist":"Toto","audioUrl":""},{"id":"cf0e7652-5796-4f44-99d8-b173184314e5","title":"Take on Me","artist":"a-ha","audioUrl":""},{"id":"22223469-8f32-4e6e-98ac-8f9259558c12","title":"Mr. Brightside","artist":"The Killers","audioUrl":""},{"id":"9c76c050-67ce-49d4-87e9-c1b0bc34b56a","title":"Dancing Queen","artist":"ABBA","audioUrl":""},{"id":"df032d23-57ad-4aeb-b45f-199419595815","title":"September","artist":"Earth, Wind & Fire","audioUrl":""},{"id":"f0b39e2f-abac-4b6e-b3a7-64394a1c59ea","title":"Thrill