    ),
    'rank_list'
  ) returning id into v_event_id;

  insert into public.event_games (event_id, game_id)
  select v_event_id, g from unnest(array[
    g_photo_static, g_photo_range, g_video_static, g_video_range, g_quiz, g_bingo
  ]) as g;

  insert into public.teams (event_id, slot_number, name, color, score, status) values
