    (v_event_id, 2, 'Blue Blazers', '#1E88E5', 0, 'active'),
    (v_event_id, 3, 'Green Giants', '#43A047', 0, 'active'),
    (v_event_id, 4, 'Orange Orbits', '#FB8C00', 0, 'active'),
    (v_event_id, 5, 'Purple Pulse', '#8E24AA', 0, 'active');

  insert into public.event_state (
    event_id, current_stage_index, current_question_index,
    timer_seconds, timer_running, show_scores, show_timer_on_display,
    quiz_state, bingo_state, break_timer_seconds, break_timer_running
