$$;

comment on function public.seed_organization_defaults(uuid) is
  'Creates default demo games and Full Test Event for an organization (idempotent).';

create or replace function public.trg_seed_organization_defaults()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.seed_organization_defaults(new.id);
  return new;
end;
$$;

drop trigger if exists organizations_seed_defaults on public.organizations;
create trigger organizations_seed_defaults
  after insert on public.organizations
  for each row
  execute function public.trg_seed_organization_defaults();

-- Backfill existing organizations
do $$
declare
  r record;
begin
  for r in select id from public.organizations
  loop
    perform public.seed_organization_defaults(r.id);
  end loop;
end;
$$;

grant execute on function public.seed_organization_defaults(uuid) to authenticated, service_role;
